module Ascii where

-- ASCII-Kunst ist nach `locId` indiziert (Aufrufer: `ascii (locA location)`).
--
-- (C7) `ascii 1` zeigte den Map-Text in der Garten-Location: der Index
-- ist die locId, der alte Inhalt gehoerte aber zu objId 1 (Map). Die Garten
-- hat jetzt ihr eigenes Bild, und fehlende Orte (Fluss, Thronsaal,
-- Lavasee, Canyon) sowie die Katakomben sind ergaenzt.

ascii :: Int -> IO ()

